  for (const bad of ['Org.Example.Music', 'nodots', 'org..music']) {
    expect(namespaceView({ LEXICON_PREFIX: bad, NAMESPACE_OWNERSHIP_REF: 'dns:txt' })).toEqual({
      prefix: null,
