import { routes as statusRoutes } from '../../src/http/record-status';
import type { RequestCtx } from '../../src/http/types';
import type { HarnessDO } from '../harness/harness-do';
import { makeLocalIndex } from '../harness/local-index';
import {
  ALICE,
  BOB,
  CAROL,
  deleteProof,
  FOLLOW,
  fixtureScrobble,
  follow,
  OPTS,
  putProof,
  repoFor,
  SCROBBLE,
