// W3-04 admission.ts against real DO SQLite. Proves M1.3.4/queue_full and
// M4.2.2/backfill_limits (1,024 pending snapshot jobs, then busy with nothing
// written), the hourly new-DID budget under the injected clock, and the
// admission half of M5.3.3/pending_confirmed (an unknown DID's hint is never
// projected; it admits an inactive owner plus a snapshot job). Expectations
// are hardcoded.

import { runInDurableObject } from 'cloudflare:test';
import { env } from 'cloudflare:workers';
import { fixedClock } from '@atmusic/core/test-support/clock';
import { describe, expect, it } from 'vitest';
import type { Db } from '../../src/do/db';
import {
  admit,
  MAX_PENDING_SNAPSHOT_JOBS,
  reclaimSnapshotLeases,
  SNAPSHOT_LEASE_MS,
  scheduleSnapshot,
} from '../../src/do/ingest/admission';
import { drain } from '../../src/do/ingest/verify-drain';
import { indexing } from '../../src/do/status';
import type { HarnessDO } from '../harness/harness-do';
import { counterValue, depsFor, enqueue, GET_RECORD, hint, kit } from './drain-support';

const stubFor = (name: string) => env.HARNESS.get(env.HARNESS.idFromName(name));

const T0 = Date.parse('2026-01-15T12:00:00Z');
const T0_STORAGE = '2026-01-15T12:00:00.000000000Z';

/** Every table of the schema, in a stable order: "writes nothing" means all of them are unchanged. */
function everything(db: Db): Record<string, unknown[]> {
  const tables = db
    .all<{ name: string }>(
      "SELECT name FROM sqlite_master WHERE type = 'table' AND name NOT LIKE 'sqlite_%' AND name NOT LIKE '_cf_%' ORDER BY name",
    )
    .map((r) => r.name);
  return Object.fromEntries(tables.map((t) => [t, db.all(`SELECT * FROM ${t} ORDER BY 1, 2`)]));
}

const B32 = 'abcdefghijklmnopqrstuvwxyz234567';
/** A distinct, valid did:plc for every n. */
function did(n: number): string {
  let out = '';
  for (let v = n; out.length < 24; v = Math.floor(v / 32)) out = B32[v % 32] + out;
  return `did:plc:${out}`;
}

describe('admission', () => {
  it('unknown DID admitted inactive with snapshot job; hint itself not projected', async () => {
    const k = await kit();
    const carol = k.users.Carol.did;
    const S = k.collections.scrobble;
    await k.externalPut('Carol', S, 'r10', {
      $type: S,
      artist: 'Kate Bush',
      track: 'Running Up That Hill',
      listenedAt: '2026-01-15T11:00:00Z',
      createdAt: '2026-01-15T11:00:00Z',
    });
    k.resetCalls();

    await runInDurableObject(stubFor('admission-unknown'), async (i: HarnessDO) => {
      const db = i.db;
      const m = depsFor(db, k);
      enqueue(db, [hint(k, carol, S, 'r10')]);
      const report = await drain(m, T0);
      expect(report.outcomes).toEqual([{ uri: `at://${carol}/${S}/r10`, outcome: 'admitted', detail: 'admitted' }]);

      // Inactive, recovering owner at a fresh global generation.
      expect(db.one('SELECT * FROM users WHERE did = ?', carol)).toEqual({
        did: carol,
        handle: null,
        handle_checked_at_ms: null,
        pds: null,
        joined_at: T0_STORAGE,
        indexed_at: null,
        active: 0,
        account_status: 'unknown',
        max_rev: null,
        indexing_state: 'recovering',
        generation: 1,
        stats_version: 0,
        last_snapshot_at_ms: null,
        last_status_check_ms: null,
        last_activity_ms: null,
      });
      expect(db.one('SELECT last_generation FROM backfill_generation')).toEqual({ last_generation: 1 });
      expect(db.all('SELECT * FROM repo_jobs')).toEqual([
        {
          did: carol,
          kind: 'snapshot',
          state: 'pending',
          generation: 1,
          reason: 'admission',
          head_rev: null,
          head_cid: null,
          frontier_json: null,
          restarts: 0,
          reactivate: 0,
          due_at: T0,
          attempts: 0,
          failure_code: null,
          updated_at_ms: T0,
        },
      ]);
      // The hint is consumed but never projected; no record state, no row.
      expect(db.all('SELECT * FROM hints')).toEqual([]);
      expect(db.all('SELECT * FROM scrobbles')).toEqual([]);
      expect(db.all('SELECT * FROM record_state')).toEqual([]);
      expect(db.all('SELECT * FROM admission')).toEqual([{ window_start_ms: T0, admitted: 1 }]);
      expect(counterValue(db, 'admitted', 'jetstream')).toBe(1);
      // Admission needs no remote call: no getRecord, no DID document.
      expect(k.pds.Carol.count(GET_RECORD)).toBe(0);
      expect(k.transport.calls.count()).toBe(0);
      // The DID reports recovering until a complete snapshot activates it.
      expect(indexing(db, T0, { mode: 'socket', did: carol })).toEqual({
        state: 'recovering',
        caughtUp: false,
        lastIndexedAt: null,
        lagSeconds: null,
      });
      expect(db.one('SELECT state FROM repo_jobs WHERE did = ?', carol)).toEqual({ state: 'pending' });

      // A second hint for the now-known (inactive) DID does not admit it again.
      expect(admit(db, carol, 'notify', T0)).toEqual({ status: 'known' });
      expect(db.one('SELECT last_generation FROM backfill_generation')).toEqual({ last_generation: 1 });
    });
  });

  it('1,024 pending jobs → next admission busy and writes nothing', async () => {
    await runInDurableObject(stubFor('admission-cap'), (i: HarnessDO) => {
      const db = i.db;
      // 1,023 queued jobs for known DIDs, each at its own generation.
      db.tx(() => {
        for (let n = 1; n < MAX_PENDING_SNAPSHOT_JOBS; n++) {
          db.run(`INSERT INTO users(did, joined_at, generation) VALUES (?, ?, ?)`, did(n), T0_STORAGE, n);
          db.run(
            `INSERT INTO repo_jobs(did, kind, state, generation, due_at, updated_at_ms)
             VALUES (?, 'snapshot', ?, ?, ?, ?)`,
            did(n),
            n % 2 === 0 ? 'pending' : 'failed',
            n,
            T0,
            T0,
          );
        }
        db.run('UPDATE backfill_generation SET last_generation = ?', MAX_PENDING_SNAPSHOT_JOBS - 1);
      });
      // A running and a complete job are not queued work.
      db.run(
        "INSERT INTO repo_jobs(did, kind, state, due_at, updated_at_ms) VALUES (?, 'snapshot', 'running', ?, ?)",
        did(5000),
        T0,
        T0,
      );
      db.run(
        "INSERT INTO repo_jobs(did, kind, state, due_at, updated_at_ms) VALUES (?, 'snapshot', 'complete', ?, ?)",
        did(5001),
        T0,
        T0,
      );

      // The 1,024th fits (hourly budget is not the limit here).
      expect(admit(db, did(1024), 'discovery', T0)).toEqual({ status: 'admitted', generation: 1024 });
      expect(
        db.one("SELECT count(*) AS n FROM repo_jobs WHERE kind = 'snapshot' AND state IN ('pending','failed')"),
      ).toEqual({
        n: 1024,
      });

      // The next one is busy and writes nothing at all.
      const before = everything(db);
      expect(admit(db, did(1025), 'discovery', T0)).toEqual({ status: 'busy', reason: 'pending_cap' });
      expect(everything(db)).toEqual(before);
      expect(db.one('SELECT did FROM users WHERE did = ?', did(1025))).toBeNull();
      // A known DID asking for a new snapshot is bounded the same way.
      db.run("UPDATE repo_jobs SET state = 'complete' WHERE did = ?", did(5000));
      db.run('INSERT INTO users(did, joined_at, generation) VALUES (?, ?, 7)', did(5000), T0_STORAGE);
      const before2 = everything(db);
      expect(scheduleSnapshot(db, did(5000), 'coalesced', T0)).toEqual({ status: 'busy' });
      expect(everything(db)).toEqual(before2);

      // One queued job completes: the next admission fits again, with a fresh generation.
      db.run("UPDATE repo_jobs SET state = 'complete' WHERE did = ?", did(2));
      expect(admit(db, did(1025), 'discovery', T0)).toEqual({ status: 'admitted', generation: 1025 });
      expect(db.one('SELECT active, indexing_state, generation FROM users WHERE did = ?', did(1025))).toEqual({
        active: 0,
        indexing_state: 'recovering',
        generation: 1025,
      });
      expect(
        db.one("SELECT state, generation, reason FROM repo_jobs WHERE did = ? AND kind = 'snapshot'", did(1025)),
      ).toEqual({
        state: 'pending',
        generation: 1025,
        reason: 'admission',
      });
      expect(counterValue(db, 'admitted', 'discovery')).toBe(2);
    });
  });

  it('scheduleSnapshot never discards or delays a walk: a started walk records one rescan request', async () => {
    await runInDurableObject(stubFor('admission-rescan'), (i: HarnessDO) => {
      const db = i.db;
      const H0 = 'bafyreih0h0h0h0h0h0h0h0h0h0h0h0h0h0h0h0h0h0h0h0h0h0h0h0h0';
      const FRONTIER = '{"stack":[],"lastKey":"com.example.atmusic.scrobble/r10"}';
      const jobs = [
        // [did, state, job generation, restarts, frontier, head, due_at, failure]
        [did(1), 'pending', 9, 0, null, null, T0 + 60_000, null], // queued, walk not started
        [did(2), 'pending', 9, 1, FRONTIER, H0, T0 + 60_000, null], // between slices at H0
        [did(3), 'running', 9, 2, FRONTIER, H0, T0 + 60_000, null], // a slice in flight at H0
        [did(4), 'failed', 9, 6, FRONTIER, H0, T0 + 3_600_000, 'repository_changed'], // in backoff
        [did(5), 'complete', 9, 3, null, H0, T0 + 60_000, null],
        [did(6), 'running', 8, 2, FRONTIER, H0, T0 + 60_000, null], // superseded by a deactivation
      ] as const;
      for (const [d, state, generation, restarts, frontier, head, due, failure] of jobs) {
        db.run('INSERT INTO users(did, joined_at, generation) VALUES (?, ?, 9)', d, T0_STORAGE);
        db.run(
          `INSERT INTO repo_jobs(did, kind, state, generation, reason, head_rev, head_cid, frontier_json, restarts,
             reactivate, due_at, attempts, failure_code, updated_at_ms)
           VALUES (?, 'snapshot', ?, ?, 'gap', '3l2aaaaaaaa22', ?, ?, ?, 1, ?, 0, ?, ?)`,
          d,
          state,
          generation,
          head,
          frontier,
          restarts,
          due,
          failure,
          T0 - 1_000,
        );
      }
      const users = db.all('SELECT * FROM users ORDER BY did');
      const jobRows = () =>
        db.all(
          `SELECT did, state, generation, reason, head_rev, head_cid, frontier_json, restarts, reactivate, due_at,
             attempts, failure_code, updated_at_ms FROM repo_jobs WHERE kind = 'snapshot' ORDER BY did`,
        );

      // Three requests in a row (an attacker's notify flood is many more): the
      // walks in progress keep their frontier, head, epoch, due time and lease.
      for (let n = 1; n <= 3; n++) {
        const results = jobs.map(([d]) => scheduleSnapshot(db, d, 'coalesced', T0 + n));
        expect(results).toEqual([
          { status: 'already', generation: 9, state: 'pending' },
          { status: 'already', generation: 9, state: 'pending' },
          { status: 'already', generation: 9, state: 'running' },
          { status: 'already', generation: 9, state: 'failed' },
          // The complete job (and then the superseded walk) is (re)created once,
          // after which it is a pending walk not yet started.
          n === 1 ? { status: 'scheduled', generation: 9 } : { status: 'already', generation: 9, state: 'pending' },
          n === 1 ? { status: 'scheduled', generation: 9 } : { status: 'already', generation: 9, state: 'pending' },
        ]);
      }
      const kept = { generation: 9, head_rev: '3l2aaaaaaaa22', reactivate: 1 };
      expect(jobRows()).toEqual([
        // Not started: its later claim covers every request; only pulled forward.
        {
          did: did(1),
          state: 'pending',
          reason: 'gap',
          head_cid: null,
          frontier_json: null,
          restarts: 0,
          due_at: T0 + 1,
          attempts: 0,
          failure_code: null,
          updated_at_ms: T0 + 3,
          ...kept,
        },
        // Paused between slices: it resumes its frontier at H0 when due, epoch unchanged;
        // three requests, one rescan when it completes.
        {
          did: did(2),
          state: 'pending',
          reason: 'gap',
          head_cid: H0,
          frontier_json: FRONTIER,
          restarts: 1,
          due_at: T0 + 60_000,
          attempts: 3,
          failure_code: null,
          updated_at_ms: T0 - 1_000,
          ...kept,
        },
        // In flight: still running with the lease token it claimed (T0 - 1000), so its
        // guarded writes still land.
        {
          did: did(3),
          state: 'running',
          reason: 'gap',
          head_cid: H0,
          frontier_json: FRONTIER,
          restarts: 2,
          due_at: T0 + 60_000,
          attempts: 3,
          failure_code: null,
          updated_at_ms: T0 - 1_000,
          ...kept,
        },
        // Failed: its backoff, failure and restarts are not reset by requests.
        {
          did: did(4),
          state: 'failed',
          reason: 'gap',
          head_cid: H0,
          frontier_json: FRONTIER,
          restarts: 6,
          due_at: T0 + 3_600_000,
          attempts: 0,
          failure_code: 'repository_changed',
          updated_at_ms: T0 - 1_000,
          ...kept,
        },
        // Complete: re-created fresh with the new reason.
        {
          did: did(5),
          state: 'pending',
          reason: 'coalesced',
          head_cid: null,
          frontier_json: null,
          restarts: 0,
          due_at: T0 + 1,
          attempts: 0,
          failure_code: null,
          updated_at_ms: T0 + 3,
          ...kept,
        },
        // A walk of generation 8: restarted fresh at generation 9 (its slice misses the
        // generation guard), then an ordinary not-started walk.
        {
          did: did(6),
          state: 'pending',
          reason: 'gap',
          head_cid: null,
          frontier_json: null,
          restarts: 0,
          due_at: T0 + 1,
          attempts: 0,
          failure_code: null,
          updated_at_ms: T0 + 3,
          ...kept,
        },
      ]);
      // The users rows are never written (a deactivation still supersedes the job).
      expect(db.all('SELECT * FROM users ORDER BY did')).toEqual(users);
      expect(counterValue(db, 'snapshot_scheduled', 'coalesced')).toBe(2);
      expect(counterValue(db, 'snapshot_rescan', 'coalesced')).toBe(6);
    });
  });

  it('reclaimSnapshotLeases returns orphaned running rows to pending with frontier, head and restarts kept', async () => {
    await runInDurableObject(stubFor('admission-reclaim'), (i: HarnessDO) => {
      const db = i.db;
      const H0 = 'bafyreih0h0h0h0h0h0h0h0h0h0h0h0h0h0h0h0h0h0h0h0h0h0h0h0h0';
      const FRONTIER = '{"stack":[],"lastKey":"com.example.atmusic.scrobble/r10"}';
      const jobs = [
        // [did, state, lease token updated_at_ms]
        [did(1), 'running', T0 - SNAPSHOT_LEASE_MS], // lease expired
        [did(2), 'running', T0 - SNAPSHOT_LEASE_MS + 1], // a live slice
        [did(3), 'pending', T0 - 2 * SNAPSHOT_LEASE_MS], // between slices: not running, untouched
        [did(4), 'running', T0 + 5_000], // a token ahead of the clock
      ] as const;
      for (const [d, state, token] of jobs) {
        db.run('INSERT INTO users(did, joined_at, generation) VALUES (?, ?, 4)', d, T0_STORAGE);
        db.run(
          `INSERT INTO repo_jobs(did, kind, state, generation, reason, head_rev, head_cid, frontier_json, restarts,
             due_at, attempts, updated_at_ms)
           VALUES (?, 'snapshot', ?, 4, 'admission', '3l2aaaaaaaa22', ?, ?, 2, ?, 1, ?)`,
          d,
          state,
          H0,
          FRONTIER,
          T0 + 60_000,
          token,
        );
      }
      const jobRows = () =>
        db.all(
          `SELECT did, state, head_cid, frontier_json, restarts, due_at, attempts, updated_at_ms FROM repo_jobs
           ORDER BY did`,
        );
      const walk = { head_cid: H0, frontier_json: FRONTIER, restarts: 2, attempts: 1 };
      expect(SNAPSHOT_LEASE_MS).toBe(900_000);

      // In a live instance: only the expired lease, fenced by a new token.
      expect(reclaimSnapshotLeases(db, T0)).toEqual([did(1)]);
      expect(jobRows()).toEqual([
        { did: did(1), state: 'pending', due_at: T0, updated_at_ms: T0, ...walk },
        { did: did(2), state: 'running', due_at: T0 + 60_000, updated_at_ms: T0 - SNAPSHOT_LEASE_MS + 1, ...walk },
        { did: did(3), state: 'pending', due_at: T0 + 60_000, updated_at_ms: T0 - 2 * SNAPSHOT_LEASE_MS, ...walk },
        { did: did(4), state: 'running', due_at: T0 + 60_000, updated_at_ms: T0 + 5_000, ...walk },
      ]);
      // A slice that held did(1)'s old lease misses its guard and writes nothing.
      expect(
        db.run(
          `UPDATE repo_jobs SET frontier_json = 'late' WHERE did = ? AND kind = 'snapshot'
             AND state = 'running' AND generation = 4 AND updated_at_ms = ?`,
          did(1),
          T0 - SNAPSHOT_LEASE_MS,
        ),
      ).toMatchObject({ rowsWritten: 0 });
      expect(db.one('SELECT frontier_json FROM repo_jobs WHERE did = ?', did(1))).toEqual({ frontier_json: FRONTIER });

      // At IndexDO start-up every running row is orphaned (after eviction no slice survives),
      // and each new token is strictly newer than the one its slice held, even ahead of the clock.
      expect(reclaimSnapshotLeases(db, T0, { all: true })).toEqual([did(2), did(4)]);
      expect(jobRows()).toEqual([
        { did: did(1), state: 'pending', due_at: T0, updated_at_ms: T0, ...walk },
        { did: did(2), state: 'pending', due_at: T0, updated_at_ms: T0, ...walk },
        { did: did(3), state: 'pending', due_at: T0 + 60_000, updated_at_ms: T0 - 2 * SNAPSHOT_LEASE_MS, ...walk },
        { did: did(4), state: 'pending', due_at: T0, updated_at_ms: T0 + 5_001, ...walk },
      ]);
      expect(counterValue(db, 'snapshot_reclaimed', 'lease')).toBe(1);
      expect(counterValue(db, 'snapshot_reclaimed', 'startup')).toBe(2);
      // Nothing left to reclaim.
      expect(reclaimSnapshotLeases(db, T0, { all: true })).toEqual([]);
    });
  });

  it('hourly budget enforced with injected clock', async () => {
    await runInDurableObject(stubFor('admission-hourly'), (i: HarnessDO) => {
      const db = i.db;
      const clock = fixedClock('2026-01-15T12:00:00Z');
      for (let n = 1; n <= 50; n++) {
        // Spread across the hour: the window is the clock hour [12:00, 13:00).
        clock.set(`2026-01-15T12:${String(n).padStart(2, '0')}:00Z`);
        expect(admit(db, did(n), 'notify', clock.nowMs())).toEqual({ status: 'admitted', generation: n });
      }
      expect(db.all('SELECT * FROM admission')).toEqual([{ window_start_ms: T0, admitted: 50 }]);

      // The 51st in the same hour is busy and writes nothing.
      clock.set('2026-01-15T12:59:59.999Z');
      const before = everything(db);
      expect(admit(db, did(51), 'notify', clock.nowMs())).toEqual({ status: 'busy', reason: 'hourly_budget' });
      expect(everything(db)).toEqual(before);

      // The next window opens at 13:00:00 by the injected clock.
      clock.advance(1);
      expect(clock.nowMs()).toBe(T0 + 3_600_000);
      expect(admit(db, did(51), 'notify', clock.nowMs())).toEqual({ status: 'admitted', generation: 51 });
      // The old window is pruned; the new one counts from 1.
      expect(db.all('SELECT * FROM admission')).toEqual([{ window_start_ms: T0 + 3_600_000, admitted: 1 }]);
      expect(db.one("SELECT count(*) AS n FROM users WHERE active = 0 AND indexing_state = 'recovering'")).toEqual({
        n: 51,
      });
      expect(counterValue(db, 'admitted', 'notify')).toBe(51);
      // A custom budget (e.g. a stricter deployment) is honoured the same way.
      expect(admit(db, did(52), 'notify', clock.nowMs(), { hourlyBudget: 1 })).toEqual({
        status: 'busy',
        reason: 'hourly_budget',
      });
    });
  });
});

baselineSources.worker/test/ingest/discovery.test.ts:
// W4-03 discovery.ts: relay listReposByCollection paging into bounded
// admission (ADR 0004 §5.4 hint sources, §5.5 gap recovery, §5.6; amendment
// A6), against real DO SQLite and the fixture relay. A relay listing is a
// hint naming only a DID: it may create an inactive users row and a pending
// snapshot job, never a projected record. Every expected value is hardcoded
// from the relay contents set up here.

import { runInDurableObject } from 'cloudflare:test';
import { env } from 'cloudflare:workers';
import { type FixtureKit, seedReadModels } from '@atmusic/atproto/test-support/read-models';
import type { FixtureTransport } from '@atmusic/atproto/test-support/router-transport';
import { describe, expect, it } from 'vitest';
import type { Db } from '../../src/do/db';
import {
  DISCOVERY_MAX_CURSOR_CHARS,
  DISCOVERY_STATE_COUNTER,
  type DiscoveryReport,
  discover,
  gapDiscoveryPending,
  LIST_REPOS_BY_COLLECTION,
  readDiscoveryState,
  requestGapDiscovery,
} from '../../src/do/ingest/discovery';
import { GAP_SCAN_DONE, maybeClearGap } from '../../src/do/ingest/snapshot-job';
import { updateCheckpointBookkeeping } from '../../src/do/status';
import { dueAt, runDue, type TimerHandlers } from '../../src/do/timers';
import type { HarnessDO } from '../harness/harness-do';
import { NOW_STORAGE, seedUser } from '../write/support';
import { depsFor, kit } from './drain-support';

const stubFor = (name: string) => env.HARNESS.get(env.HARNESS.idFromName(name));

const T0 = Date.parse('2026-01-15T12:00:00Z');
const HOUR = 3_600_000;
const DAY = 24 * HOUR;

// did:plc identifiers in byte order of their index (base32 alphabet sorted).
const B32 = '234567abcdefghijklmnopqrstuvwxyz';
function syntheticDid(group: 'f' | 's', index: number): string {
  const enc = B32[(index >> 10) & 31]! + B32[(index >> 5) & 31]! + B32[index & 31]!;
  return `did:plc:${group}${'a'.repeat(20)}${enc}`;
}

function projection(db: Db) {
  return {
    scrobbles: db.all('SELECT * FROM scrobbles'),
    follows: db.all('SELECT * FROM follows'),
    record_state: db.all('SELECT * FROM record_state'),
    hints: db.all('SELECT * FROM hints'),
  };
}

const EMPTY = { scrobbles: [], follows: [], record_state: [], hints: [] };

function admittedUsers(db: Db) {
  return db.all<{ did: string; active: number; account_status: string; indexing_state: string }>(
    'SELECT did, active, account_status, indexing_state FROM users ORDER BY did',
  );
}

function snapshotJobs(db: Db) {
  return db.all<{ did: string; state: string; reason: string }>(
    `SELECT did, state, reason FROM repo_jobs WHERE kind = 'snapshot' ORDER BY did`,
  );
}

function relayPages(k: FixtureKit) {
  return k.relay.calls.filter({ nsid: LIST_REPOS_BY_COLLECTION }).map((c) => ({
    collection: c.params.collection?.[0],
    limit: c.params.limit?.[0],
    cursor: c.params.cursor?.[0] ?? null,
  }));
}

/** Every call that would fetch, verify or resolve a record or an identity. */
function recordCalls(k: FixtureKit): number {
  return (['Alice', 'Bob', 'Carol'] as const).reduce((n, u) => n + k.pds[u].calls.count(), 0) + k.plc.count();
}

describe('relay discovery', () => {
  it('listReposByCollection pages admit DIDs within budget and never project records', async () => {
    const k = await kit();
    await seedReadModels(k); // the relay lists Alice, Bob and Carol (scrobble) and Alice (follow)
    const alice = k.users.Alice.did;
    const bob = k.users.Bob.did;
    const carol = k.users.Carol.did;
    const S = k.collections.scrobble;
    const F = k.collections.follow;
    const s = Array.from({ length: 60 }, (_, i) => syntheticDid('s', i));
    const f = Array.from({ length: 3 }, (_, i) => syntheticDid('f', i));
    k.relay.add(S, ...s, 'did:example:not-resolvable');
    k.relay.add(F, ...f);
    // Scrobble listing (DID order): did:example (invalid), Alice (known), Bob, Carol
    // (suppressed), s0..s59 — 64 entries, 13 pages of 5. Follow listing: Alice, f0..f2.
    expect(k.relay.repos(S).length).toBe(64);
    k.resetCalls();

    await runInDurableObject(stubFor('discovery-pages'), async (i: HarnessDO) => {
      const db = i.db;
      const m = depsFor(db, k);
      seedUser(db, alice);
      db.run('INSERT INTO suppression(did, suppressed_at) VALUES (?, ?)', carol, NOW_STORAGE);
      const aliceBefore = db.one('SELECT * FROM users WHERE did = ?', alice);

      // Run 1: the page budget (10 pages) ends it after 50 listed entries.
      const r1 = await discover(m, T0, { pageLimit: 5 });
      expect(r1).toMatchObject({ pass: 'daily', pages: 10, known: 1, suppressed: 1, invalid: 1, stop: 'page_budget' });
      expect(r1.admitted).toEqual([bob, ...s.slice(0, 46)]);
      const pages1 = relayPages(k);
      expect(pages1.length).toBe(10);
      expect(pages1[0]).toEqual({ collection: S, limit: '5', cursor: null });
      expect(pages1[1]).toEqual({ collection: S, limit: '5', cursor: s[0] });
      expect(pages1[9]).toEqual({ collection: S, limit: '5', cursor: s[40] });
      expect(readDiscoveryState(db)).toEqual({ pass: 'daily', collection: 0, cursor: s[45], pages: 10 });
      expect(dueAt(db, 'discovery')).toBe(T0 + DAY);

      // Run 2, same admission hour: 3 more fill the hourly budget of 50; s49 is refused,
      // so the position stays at the start of that page.
      k.resetCalls();
      const r2 = await discover(m, T0 + 60_000, { pageLimit: 5 });
      expect(r2).toMatchObject({ pages: 1, stop: 'admission_busy', detail: 'hourly_budget' });
      expect(r2.admitted).toEqual(s.slice(46, 49));
      expect(relayPages(k)).toEqual([{ collection: S, limit: '5', cursor: s[45] }]);
      expect(readDiscoveryState(db)).toEqual({ pass: 'daily', collection: 0, cursor: s[45], pages: 10 });
      expect(db.one('SELECT admitted FROM admission')).toEqual({ admitted: 50 });

      // Run 3, next hour: the refused page is read again (s46..s48 are known now), the
      // scrobble listing ends, then the follow listing; the pass completes.
      k.resetCalls();
      const r3 = await discover(m, T0 + HOUR, { pageLimit: 5 });
      expect(r3).toMatchObject({ pages: 4, known: 4, stop: 'complete' });
      expect(r3.admitted).toEqual([...s.slice(49), ...f]);
      expect(relayPages(k)).toEqual([
        { collection: S, limit: '5', cursor: s[45] },
        { collection: S, limit: '5', cursor: s[50] },
        { collection: S, limit: '5', cursor: s[55] },
        { collection: F, limit: '5', cursor: null },
      ]);
      expect(readDiscoveryState(db)).toBeNull();
      expect(db.all('SELECT * FROM counters WHERE name = ?', DISCOVERY_STATE_COUNTER)).toEqual([]);
      expect(dueAt(db, 'discovery')).toBe(T0 + HOUR + DAY);

      // Admission only: inactive, recovering users plus one pending snapshot job each.
      const admitted = [bob, ...s, ...f].sort();
      expect(admitted.length).toBe(64);
      expect(admittedUsers(db).filter((u) => u.did !== alice)).toEqual(
        admitted.map((did) => ({ did, active: 0, account_status: 'unknown', indexing_state: 'recovering' })),
      );
      expect(snapshotJobs(db)).toEqual(admitted.map((did) => ({ did, state: 'pending', reason: 'admission' })));
      expect(db.one("SELECT value FROM counters WHERE name = 'admitted' AND label = 'discovery'")).toEqual({
        value: 64,
      });
      // The known account is untouched; the suppressed one and the invalid DID get nothing.
      expect(db.one('SELECT * FROM users WHERE did = ?', alice)).toEqual(aliceBefore);
      expect(db.one('SELECT did FROM users WHERE did = ?', carol)).toBeNull();
      expect(db.one("SELECT did FROM users WHERE did LIKE 'did:example:%'")).toBeNull();
      expect(dueAt(db, 'snapshot')).toBe(T0);

      // Never a record: no projection row, no hint, and no PDS / PLC request at all.
      expect(projection(db)).toEqual(EMPTY);
      expect(recordCalls(k)).toBe(0);
    });
  });

  it('gap recovery runs one full pass from the start and stays pending until it ends', async () => {
    const k = await kit();
    const S = k.collections.scrobble;
    const s = Array.from({ length: 12 }, (_, i) => syntheticDid('s', i));
    k.relay.add(S, ...s);

    await runInDurableObject(stubFor('discovery-gap'), async (i: HarnessDO) => {
      const db = i.db;
      const m = depsFor(db, k);
      // A daily pass is half way through the scrobble listing.
      await discover(m, T0, { pageLimit: 5, pages: 1 });
      expect(readDiscoveryState(db)).toEqual({ pass: 'daily', collection: 0, cursor: s[4], pages: 1 });
      expect(gapDiscoveryPending(db)).toBe(false);

      // Gap recovery: one pass from the beginning, due now.
      requestGapDiscovery(db, T0 + 60_000);
      expect(readDiscoveryState(db)).toEqual({ pass: 'gap', collection: 0, cursor: null, pages: 0 });
      expect(gapDiscoveryPending(db)).toBe(true);
      expect(dueAt(db, 'discovery')).toBe(T0 + 60_000);

      // A relay outage keeps the position; the gap pass retries within the hour.
      k.relay.fail({ nsid: LIST_REPOS_BY_COLLECTION }, { kind: 'status', status: 503 });
      k.resetCalls();
      const failed = await discover(m, T0 + 60_000, { pageLimit: 5 });
      expect(failed).toMatchObject({ pages: 0, stop: 'relay_error', detail: 'http_503' });
      expect(readDiscoveryState(db)).toEqual({ pass: 'gap', collection: 0, cursor: null, pages: 0 });
      expect(dueAt(db, 'discovery')).toBe(T0 + 60_000 + HOUR);

      // Two pages per run: the gap pass continues a minute later until it ends.
      const a = await discover(m, T0 + HOUR, { pageLimit: 5, pages: 2 });
      expect(a).toMatchObject({ pass: 'gap', pages: 2, stop: 'page_budget' });
      expect(gapDiscoveryPending(db)).toBe(true);
      expect(dueAt(db, 'discovery')).toBe(T0 + HOUR + 60_000);
      const b = await discover(m, T0 + HOUR + 60_000, { pageLimit: 5, pages: 2 });
      expect(b).toMatchObject({ pass: 'gap', pages: 2, stop: 'complete' });
      expect(gapDiscoveryPending(db)).toBe(false);
      expect(dueAt(db, 'discovery')).toBe(T0 + HOUR + 60_000 + DAY);
      expect(relayPages(k).map((p) => [p.collection, p.cursor])).toEqual([
        [S, null], // the 503
        [S, null],
        [S, s[4]],
        [S, s[9]],
        [k.collections.follow, null],
      ]);
      expect(snapshotJobs(db).map((j) => j.did)).toEqual(s);
      expect(projection(db)).toEqual(EMPTY);
      expect(recordCalls(k)).toBe(0);
    });
  });

  it('a gap request that lands while a relay page is in flight survives the run', async () => {
    const k = await kit();
    const S = k.collections.scrobble;
    const F = k.collections.follow;
    const s = Array.from({ length: 12 }, (_, i) => syntheticDid('s', i));
    k.relay.add(S, ...s);

    await runInDurableObject(stubFor('discovery-gap-race'), async (i: HarnessDO, ctx: DurableObjectState) => {
      const db = i.db;
      const base = depsFor(db, k);
      // A daily pass is one page into the scrobble listing; the next run is due tomorrow.
      await discover(base, T0, { pageLimit: 5, pages: 1 });
      expect(readDiscoveryState(db)).toEqual({ pass: 'daily', collection: 0, cursor: s[4], pages: 1 });
      expect(dueAt(db, 'discovery')).toBe(T0 + DAY);

      // The injected transport lets gap recovery start (the DO input gate is open
      // during outbound I/O) after the relay answered and before the run sees the page.
      const T1 = T0 + DAY;
      let gapRequests = 0;
      let armed = true;
      const inner = k.transport;
      const transport = Object.assign(
        async (req: Request) => {
          const res = await inner(req);
          if (armed && new URL(req.url).pathname.endsWith(LIST_REPOS_BY_COLLECTION)) {
            armed = false;
            gapRequests++;
            requestGapDiscovery(db, T1);
          }
          return res;
        },
        { fixture: true as const, calls: inner.calls, hostnames: inner.hostnames },
      ) satisfies FixtureTransport;
      const m = { ...base, transport };
      const reports: DiscoveryReport[] = [];
      const noop = async () => {};
      const handlers: TimerHandlers = {
        drain: noop,
        snapshot: noop,
        'jetstream-watchdog': noop,
        'status-sweep': noop,
        'identity-sweep': noop,
        discovery: async (at) => {
          reports.push(await discover(m, at, { pageLimit: 5, pages: 1 }));
        },
        gc: noop,
      };
      k.resetCalls();

      // The alarm claims the daily run. Its page (s5..s9) arrives after the gap request
      // reset the position: the run admits nothing from it, writes no position, and
      // leaves the gap pass due now instead of pushing the timer to tomorrow.
      const first = await runDue(ctx.storage, db, T1, handlers, { maxRuns: 7 });
      // (`snapshot` is the one-shot timer the first daily run armed for its admissions.)
      expect(first.ran).toEqual(['snapshot', 'discovery']);
      expect(gapRequests).toBe(1);
      expect(reports[0]).toMatchObject({ pass: 'daily', pages: 0, admitted: [], stop: 'superseded' });
      expect(readDiscoveryState(db)).toEqual({ pass: 'gap', collection: 0, cursor: null, pages: 0 });
      expect(gapDiscoveryPending(db)).toBe(true);
      expect(dueAt(db, 'discovery')).toBe(T1);
      expect(snapshotJobs(db).map((j) => j.did)).toEqual(s.slice(0, 5));

      // The next alarms run the gap pass from the start of the listing to its end, a
      // minute apart (one page per run here), and only then is the pass over.
      for (let n = 0, at = T1; n < 10 && gapDiscoveryPending(db); n++, at += 60_000) {
        expect(dueAt(db, 'discovery')).toBe(at);
        await runDue(ctx.storage, db, at, handlers, { maxRuns: 7 });
      }
      expect(gapDiscoveryPending(db)).toBe(false);
      expect(reports.slice(1).map((r) => [r.pass, r.stop])).toEqual([
        ['gap', 'page_budget'],
        ['gap', 'page_budget'],
        ['gap', 'page_budget'],
        ['gap', 'complete'],
      ]);
      expect(relayPages(k).map((p) => [p.collection, p.cursor])).toEqual([
        [S, s[4]], // the superseded daily page
        [S, null],
        [S, s[4]],
        [S, s[9]],
        [F, null],
      ]);
      expect(dueAt(db, 'discovery')).toBe(T1 + 3 * 60_000 + DAY);
      expect(snapshotJobs(db).map((j) => j.did)).toEqual(s);
      expect(projection(db)).toEqual(EMPTY);
      expect(recordCalls(k)).toBe(0);
    });
  });

  it('permanently malformed relay page fails bounded and does not wedge gap discovery', async () => {
    const k = await kit();
    const S = k.collections.scrobble;
    const F = k.collections.follow;
    const s = Array.from({ length: 8 }, (_, i) => syntheticDid('s', i));
    const f = syntheticDid('f', 0);
    k.relay.add(S, ...s);
    k.relay.add(F, f);

    await runInDurableObject(stubFor('discovery-malformed'), async (i: HarnessDO) => {
      const db = i.db;
      const base = depsFor(db, k);
      // The relay answers two positions with a permanently malformed page: the second
      // scrobble page holds a non-object repos entry, the first follow page an over-long cursor.
      const inner = k.transport;
      const served: Array<[string | undefined, string | null, 'ok' | 'malformed']> = [];
      const transport = Object.assign(
        async (req: Request) => {
          const url = new URL(req.url);
          if (url.pathname.endsWith(LIST_REPOS_BY_COLLECTION)) {
            const collection = url.searchParams.get('collection') ?? undefined;
            const cursor = url.searchParams.get('cursor');
            if (collection === S && cursor === s[4]) {
              served.push([collection, cursor, 'malformed']);
              return Response.json({ repos: [{ did: s[5] }, 42], cursor: s[7] });
            }
            if (collection === F && cursor === null) {
              served.push([collection, cursor, 'malformed']);
              return Response.json({ repos: [{ did: f }], cursor: 'c'.repeat(DISCOVERY_MAX_CURSOR_CHARS + 1) });
            }
            served.push([collection, cursor, 'ok']);
          }
          return inner(req);
        },
        { fixture: true as const, calls: inner.calls, hostnames: inner.hostnames },
      ) satisfies FixtureTransport;
      const m = { ...base, transport };

      // Gap recovery is waiting for this pass (the snapshot scan itself is done).
      updateCheckpointBookkeeping(db, { pendingGap: true, gapScanAfterDid: GAP_SCAN_DONE });
      requestGapDiscovery(db, T0);
      expect(gapDiscoveryPending(db)).toBe(true);

      const runs: DiscoveryReport[] = [];
      let at = T0;
      for (let n = 0; n < 10 && gapDiscoveryPending(db); n++) {
        expect(dueAt(db, 'discovery')).toBe(at);
        runs.push(await discover(m, at, { pageLimit: 5 }));
        // While the gap's pass runs, gap recovery cannot finish (the scan alone is done).
        if (gapDiscoveryPending(db)) expect(maybeClearGap(db)).toBe(false);
        at = dueAt(db, 'discovery')!;
      }
      // Bounded: three answers per bad position, then that listing is given up and the pass ends.
      expect(gapDiscoveryPending(db)).toBe(false);
      expect(runs.map((r) => [r.stop, r.detail ?? null, r.abandoned ?? []])).toEqual([
        ['relay_error', 'malformed_page', []],
        ['relay_error', 'malformed_page', []],
        ['relay_error', 'malformed_page', [S]],
        ['relay_error', 'malformed_page', []],
        ['complete', null, [F]],
      ]);
      expect(served).toEqual([
        [S, null, 'ok'],
        [S, s[4], 'malformed'],
        [S, s[4], 'malformed'],
        [S, s[4], 'malformed'],
        [F, null, 'malformed'],
        [F, null, 'malformed'],
        [F, null, 'malformed'],
      ]);
      // Each retry waited the gap pass's relay retry interval; the last run returned to the daily cadence.
      expect(runs.map((r) => r.nextDueAt)).toEqual([
        T0 + HOUR,
        T0 + 2 * HOUR,
        T0 + 3 * HOUR,
        T0 + 4 * HOUR,
        T0 + 4 * HOUR + DAY,
      ]);
      expect(readDiscoveryState(db)).toBeNull();
      // The errors are recorded: every malformed answer, and each listing given up.
      const counters = (name: string) =>
        db.all<{ label: string; value: number }>(
          'SELECT label, value FROM counters WHERE name = ? ORDER BY label',
          name,
        );
      expect(counters('discovery_failed')).toEqual([{ label: 'malformed_page', value: 6 }]);
      expect(counters('discovery_abandoned')).toEqual([
        { label: F, value: 1 },
        { label: S, value: 1 },
      ]);
      expect(counters('discovery_passes')).toEqual([{ label: 'gap', value: 1 }]);
      // Only the good first page was admitted; nothing from a malformed page.
      expect(snapshotJobs(db).map((j) => j.did)).toEqual(s.slice(0, 5));
      expect(projection(db)).toEqual(EMPTY);
      expect(recordCalls(k)).toBe(0);
      // With its discovery pass over, gap recovery can finish: pending_gap clears.
      expect(db.one('SELECT pending_gap FROM ingest_checkpoint')).toEqual({ pending_gap: 1 });
      expect(maybeClearGap(db)).toBe(true);
      expect(db.one('SELECT pending_gap FROM ingest_checkpoint')).toEqual({ pending_gap: 0 });
    });
  });
});

