      expect(follows(db, alice)).toEqual([{ ...follow, subject: k.users.Bob.did, revision: head.rev }]);
      expect(recordStates(db, alice)).toEqual(
        [follow, ...scrobbleRows].map((r) => ({ ...r, state: 'present', revision: head.rev })),
      );
