// W4-03 sweeps.ts: the hourly account-status sweep and the daily identity
// sweep, against real DO SQLite and the fixture network (fake PDSs, PLC, DoH
// TXT and well-known handles; the production SafeFetch policy and identity
// resolver). Proves M5.2.1/handle_rename (A17 identity sweep) and the
// handle/PDS rules of ADR 0004 §5.6. History is seeded through the production
// verify drain from real signed commits; every expected value is hardcoded.

import { runInDurableObject } from 'cloudflare:test';
import { env } from 'cloudflare:workers';
import { testKey } from '@atmusic/atproto/test-support/keys';
import { FIXTURE_USERS, type FixtureKit, seedReadModels } from '@atmusic/atproto/test-support/read-models';
import type { FixtureTransport } from '@atmusic/atproto/test-support/router-transport';
import { SignedRepo } from '@atmusic/atproto/test-support/signed-repo';
import { describe, expect, it } from 'vitest';
import type { Db } from '../../src/do/db';
import { GET_REPO_STATUS } from '../../src/do/ingest/accounts';
import { cachedIdentityResolver, resolveIdentity } from '../../src/do/ingest/identity-cache';
import { identitySweep, statusSweep } from '../../src/do/ingest/sweeps';
import { drain } from '../../src/do/ingest/verify-drain';
import { history } from '../../src/do/read/history';
import { profile, resolveHandle } from '../../src/do/read/profile';
import { dueAt } from '../../src/do/timers';
import type { HarnessDO } from '../harness/harness-do';
import { seedUser } from '../write/support';
import { type Deps, depsFor, enqueue, hint, hintRows, kit } from './drain-support';

const stubFor = (name: string) => env.HARNESS.get(env.HARNESS.idFromName(name));

const T0 = Date.parse('2026-01-15T12:00:00Z');
const HOUR = 3_600_000;
const DAY = 24 * HOUR;
const ALICE_HISTORY = ['r07', 'r01', 'r02', 'r03', 'r04', 'r05', 'r06'];
const OUTSIDER = 'did:plc:zzzzzzzzzzzzzzzzzzzzzzzz';

const rkey = (uri: string) => uri.slice(uri.lastIndexOf('/') + 1);

function historyOf(m: Deps, did: string): string[] {
  return history(m, { did, limit: 100 }).rows.map((r) => rkey(r.uri));
}

function handles(db: Db): Record<string, string | null> {
  return Object.fromEntries(
    db
      .all<{ did: string; handle: string | null }>('SELECT did, handle FROM users ORDER BY did')
      .map((r) => [r.did, r.handle]),
  );
}

function projection(db: Db) {
  return {
    scrobbles: db.all('SELECT * FROM scrobbles ORDER BY uri'),
    follows: db.all('SELECT * FROM follows ORDER BY uri'),
    record_state: db.all('SELECT * FROM record_state ORDER BY uri'),
  };
}

function snapshotJobs(db: Db) {
  return db.all(`SELECT did, state, reason, generation FROM repo_jobs WHERE kind = 'snapshot' ORDER BY did`);
}

/** Publish the shared fixture and ingest every record through the production drain. */
async function seedIndexed(db: Db, m: Deps, k: FixtureKit): Promise<void> {
  const seed = await seedReadModels(k);
  for (const n of FIXTURE_USERS) seedUser(db, k.users[n].did);
  enqueue(
    db,
    [...seed.records.values()].map((r) => hint(k, r.did, r.collection, r.rkey)),
  );
  const report = await drain(m, k.clock.nowMs());
  expect(report.claimed).toBe(seed.records.size);
  expect(hintRows(db)).toEqual([]);
  k.resetCalls();
}

// ---------------------------------------------------------------------------
// Synthetic accounts for the cadence test: did:plc identifiers whose 24 base32
// characters sort by a one-letter group and then by index (the base32
// alphabet in byte order, so index order is SQLite BINARY order).

const B32 = '234567abcdefghijklmnopqrstuvwxyz';
function syntheticDid(group: 'o' | 'r', index: number): string {
  const enc = B32[(index >> 10) & 31]! + B32[(index >> 5) & 31]! + B32[index & 31]!;
  return `did:plc:${group}${'a'.repeat(20)}${enc}`;
}

describe('status sweep', () => {
  it('active-in-30d DIDs are checked hourly, others daily, 200 per run', async () => {
    const k = await kit();
    const pds = k.pds.Bob; // every synthetic account lives on one fixture PDS host
    const key = await testKey('secp256k1', 0x21, 'sweep-secp256k1');
    const O = Array.from({ length: 200 }, (_, i) => syntheticDid('o', i));
    const R = Array.from({ length: 32 }, (_, i) => syntheticDid('r', i));
    for (const did of [...O, ...R]) {
      await pds.addAccount(new SignedRepo(did, key, { clock: k.clock }));
      k.plc.register(did, { signingKey: key, pds: pds.origin, handle: null });
    }
    // Activity, relative to the second run at T0 + 1 h:
    // - O[0]: 30 days and 1 ms before it (idle → daily);
    // - O[1]: exactly 30 days before it (recent → hourly);
    // - O[2..99]: none; O[100..199]: 40 days before T0 (idle);
    // - R[*]: one day before T0 (recent).
    const activity = new Map<string, number | null>();
    O.forEach((did, i) => {
      activity.set(
        did,
        i === 0 ? T0 + HOUR - 30 * DAY - 1 : i === 1 ? T0 + HOUR - 30 * DAY : i < 100 ? null : T0 - 40 * DAY,
      );
    });
    for (const did of R) activity.set(did, T0 - DAY);

    await runInDurableObject(stubFor('sweep-cadence'), async (i: HarnessDO) => {
      const db = i.db;
      const m = depsFor(db, k);
      for (const did of [...O, ...R]) {
        seedUser(db, did);
        db.run('UPDATE users SET last_activity_ms = ? WHERE did = ?', activity.get(did) ?? null, did);
      }
      const usersBefore = db.all('SELECT did, active, account_status, generation, handle FROM users ORDER BY did');
      k.resetCalls();

      const checkedDids = () =>
        pds.calls
          .filter({ nsid: GET_REPO_STATUS })
          .map((c) => c.params.did![0]!)
          .sort();
      const lastChecks = () =>
        Object.fromEntries(
          db
            .all<{ did: string; t: number | null }>('SELECT did, last_status_check_ms AS t FROM users')
            .map((r) => [r.did, r.t]),
        );
      const run = async (now: number) => {
        pds.calls.reset();
        const report = await statusSweep(m, now);
        expect(report.checked.every((c) => c.source === 'sweep' && c.outcome === 'active')).toBe(true);
        expect(dueAt(db, 'status-sweep')).toBe(now + HOUR);
        return report;
      };

      // Run 1 (T0): every DID is unchecked; 200 per run, in DID order → all of O.
      const r1 = await run(T0);
      expect(r1.checked.length).toBe(200);
      expect(checkedDids()).toEqual(O);
      let t = lastChecks();
      expect(O.every((d) => t[d] === T0)).toBe(true);
      expect(R.every((d) => t[d] === null)).toBe(true);

      // Run 2 (T0 + 1 h): the 32 never-checked R, plus O[1] (activity exactly 30 days
      // ago, hourly). O[0] (30 days and 1 ms) and the other idle DIDs are not due.
      const r2 = await run(T0 + HOUR);
      expect(r2.checked.length).toBe(33);
      expect(checkedDids()).toEqual([O[1]!, ...R].sort());
      t = lastChecks();
      expect(t[O[0]!]).toBe(T0);
      expect(t[O[1]!]).toBe(T0 + HOUR);

      // Run 3 (T0 + 2 h): the recent R again (hourly). O[1]'s activity is now more than
      // 30 days old, so it is daily and not due.
      const r3 = await run(T0 + 2 * HOUR);
      expect(r3.checked.length).toBe(32);
      expect(checkedDids()).toEqual(R);

      // Run 4 (T0 + 24 h): 199 O are due (checked at T0) and all 32 R (checked at
      // T0 + 2 h). Only 200 are taken, oldest check first: the 199 O, then R[0].
      const r4 = await run(T0 + DAY);
      expect(r4.checked.length).toBe(200);
      expect(checkedDids()).toEqual([...O.filter((d) => d !== O[1]), R[0]!].sort());
      t = lastChecks();
      expect(R.slice(1).every((d) => t[d] === T0 + 2 * HOUR)).toBe(true);
      expect(t[O[1]!]).toBe(T0 + HOUR);

      // Run 5 (T0 + 25 h): the 31 R left over plus R[0] (hourly) and O[1] (daily, last
      // checked at T0 + 1 h).
      const r5 = await run(T0 + 25 * HOUR);
      expect(r5.checked.length).toBe(33);
      expect(checkedDids()).toEqual([O[1]!, ...R].sort());

      // Checks of active accounts change nothing but the check time.
      expect(db.all('SELECT did, active, account_status, generation, handle FROM users ORDER BY did')).toEqual(
        usersBefore,
      );
      expect(db.all('SELECT * FROM repo_jobs')).toEqual([]);
      // Never-a-relay: every call went to the account's PDS (or PLC/DoH for its identity).
      expect(k.relay.calls.count()).toBe(0);
    });
  });
});

describe('status sweep fairness', () => {
  it('a failing PDS host does not starve DIDs on healthy hosts behind it in the round-robin', async () => {
    const k = await kit();
    const failing = k.pds.Bob; // every O account: getRepoStatus answers 503
    const healthy = k.pds.Carol; // every R account
    const key = await testKey('secp256k1', 0x22, 'sweep-fair-secp256k1');
    const O = Array.from({ length: 200 }, (_, i) => syntheticDid('o', i));
    const R = Array.from({ length: 5 }, (_, i) => syntheticDid('r', i));
    for (const [server, dids] of [
      [failing, O],
      [healthy, R],
    ] as const) {
      for (const did of dids) {
        await server.addAccount(new SignedRepo(did, key, { clock: k.clock }));
        k.plc.register(did, { signingKey: key, pds: server.origin, handle: null });
      }
    }
    failing.serverError(GET_REPO_STATUS, 503, Infinity);

    await runInDurableObject(stubFor('sweep-fair'), async (i: HarnessDO) => {
      const db = i.db;
      const m = depsFor(db, k);
      // Never checked: round-robin order is DID order, so all 200 O come before any R.
      for (const did of [...O, ...R]) seedUser(db, did);
      k.resetCalls();
      const lastChecks = () =>
        Object.fromEntries(
          db
            .all<{ did: string; t: number | null }>('SELECT did, last_status_check_ms AS t FROM users')
            .map((r) => [r.did, r.t]),
        );
      const perHost = m.config.budget.perHostConcurrency;

      // Slice 1: the first 503s pause the failing host; the O behind them come back
      // host_paused without a fetch and give their slots back, so the R are checked.
      const r1 = await statusSweep(m, T0);
      const failedFetches = failing.calls.count({ nsid: GET_REPO_STATUS });
      expect(failedFetches).toBeGreaterThanOrEqual(1);
      expect(failedFetches).toBeLessThanOrEqual(perHost);
      expect(
        healthy.calls
          .filter({ nsid: GET_REPO_STATUS })
          .map((c) => c.params.did![0]!)
          .sort(),
      ).toEqual(R);
      expect(
        r1.checked
          .filter((c) => c.outcome === 'active')
          .map((c) => c.did)
          .sort(),
      ).toEqual(R);
      expect(r1.checked.filter((c) => c.outcome === 'failed').length).toBe(failedFetches);
      expect(r1.checked.filter((c) => c.outcome === 'host_paused').length).toBe(200 - failedFetches);
      let t = lastChecks();
      expect(R.every((d) => t[d] === T0)).toBe(true);
      // The O that were attempted moved back in line; the skipped ones stay first.
      expect(O.filter((d) => t[d] === T0).length).toBe(failedFetches);
      expect(O.filter((d) => t[d] === null).length).toBe(200 - failedFetches);
      expect(db.one('SELECT until_ms FROM host_backoff WHERE host = ?', k.users.Bob.host)).toEqual({
        until_ms: T0 + 5_000,
      });

      // Slice 2, an hour later: the pause has expired. Every O identity is now known, so
      // once the first 503 pauses the host again the rest are passed over at selection,
      // without an identity resolution or a fetch. The R are not due yet (daily).
      failing.calls.reset();
      healthy.calls.reset();
      k.plc.calls.reset();
      const r2 = await statusSweep(m, T0 + HOUR);
      const failed2 = failing.calls.count({ nsid: GET_REPO_STATUS });
      expect(failed2).toBeGreaterThanOrEqual(1);
      expect(failed2).toBeLessThanOrEqual(perHost);
      expect(healthy.calls.count()).toBe(0);
      expect(r2.passedOver).toBeGreaterThan(0);
      // Due: the O skipped in slice 1 (the attempted ones are idle, so daily).
      expect(r2.checked.length + r2.passedOver).toBe(200 - failedFetches);
      expect(k.plc.count()).toBeLessThanOrEqual(m.config.budget.concurrentFetches);
      t = lastChecks();
      expect(R.every((d) => t[d] === T0)).toBe(true);
      // Account state never changed: a host failure is no answer.
      expect(db.all('SELECT DISTINCT active, account_status FROM users')).toEqual([
        { active: 1, account_status: 'active' },
      ]);
      expect(db.all('SELECT * FROM repo_jobs')).toEqual([]);
    });
  });
});

describe('identity sweep', () => {
  it('handle that no longer verifies becomes null; history retained', async () => {
    const k = await kit();
    const alice = k.users.Alice.did;
    const bob = k.users.Bob.did;
    const carol = k.users.Carol.did;

    await runInDurableObject(stubFor('sweep-handle-null'), async (i: HarnessDO) => {
      const db = i.db;
      const m = depsFor(db, k);
      await seedIndexed(db, m, k);

      const first = await identitySweep(m, T0);
      expect(first.checked.map((c) => [c.did, c.outcome]).sort()).toEqual([
        [alice, 'verified'],
        [bob, 'verified'],
        [carol, 'verified'],
      ]);
      expect(handles(db)).toEqual({ [alice]: 'alice.test', [bob]: 'bob.test', [carol]: 'carol.test' });
      // Fresh resolutions: one DID document fetch per account, no cache.
      expect(k.plc.count()).toBe(3);
      expect(dueAt(db, 'identity-sweep')).toBe(T0 + DAY);
      const before = projection(db);
      const aliceBefore = db.one(
        'SELECT active, account_status, generation, max_rev, stats_version FROM users WHERE did = ?',
        alice,
      );

      // alice.test now names another DID; Alice's document still claims it.
      k.doh.setTxt('_atproto.alice.test', [`did=${OUTSIDER}`]);
      k.handles.set('alice.test', OUTSIDER);
      // Carol's DID document is briefly unavailable (transient): her handle is kept.
      k.plc.fail({ did: carol }, { kind: 'status', status: 503 });
      k.resetCalls();

      // Not due before a day has passed.
      const early = await identitySweep(m, T0 + DAY - 1);
      expect(early.checked).toEqual([]);
      expect(k.plc.count()).toBe(0);

      const second = await identitySweep(m, T0 + DAY);
      expect(second.checked.map((c) => [c.did, c.outcome]).sort()).toEqual([
        [alice, 'cleared'],
        [bob, 'verified'],
        [carol, 'failed'],
      ]);
      expect(handles(db)).toEqual({ [alice]: null, [bob]: 'bob.test', [carol]: 'carol.test' });
      expect(db.one('SELECT handle_checked_at_ms AS t FROM users WHERE did = ?', carol)).toEqual({ t: T0 + DAY });
      expect(k.plc.count(alice)).toBe(1);
      expect(k.plc.count(carol)).toBe(1);

      // History, follows and the record guards are untouched; Alice stays visible.
      expect(projection(db)).toEqual(before);
      expect(
        db.one('SELECT active, account_status, generation, max_rev, stats_version FROM users WHERE did = ?', alice),
      ).toEqual(aliceBefore);
      expect(historyOf(m, alice)).toEqual(ALICE_HISTORY);
      const p = await profile(m, alice);
      expect(p).toMatchObject({ did: alice, handle: null, totalScrobbles: 7, followingCount: 1 });
      expect(snapshotJobs(db)).toEqual([]);
      expect(db.all("SELECT label, value FROM counters WHERE name = 'handle_cleared'")).toEqual([
        { label: 'unverified', value: 1 },
      ]);
    });
  });

  it('PDS change in DID doc schedules snapshot', async () => {
    const k = await kit();
    const alice = k.users.Alice.did;

    await runInDurableObject(stubFor('sweep-pds-change'), async (i: HarnessDO) => {
      const db = i.db;
      const m = depsFor(db, k);
      await seedIndexed(db, m, k);
      await identitySweep(m, T0);
      expect(db.all('SELECT did, pds FROM users ORDER BY did')).toEqual(
        FIXTURE_USERS.map((n) => ({ did: k.users[n].did, pds: k.users[n].origin })),
      );
      expect(snapshotJobs(db)).toEqual([]);
      const before = projection(db);
      const generation = db.one<{ generation: number }>(
        'SELECT generation FROM users WHERE did = ?',
        alice,
      )!.generation;

      // Alice migrates her repository to another PDS host and updates her DID document.
      await k.pds.Bob.addAccount(k.repos.Alice, { handle: 'alice.test' });
      k.plc.setPds(alice, k.pds.Bob.origin);
      k.pds.Alice.removeAccount(alice);

      const t1 = T0 + DAY;
      const report = await identitySweep(m, t1);
      expect(report.checked.find((c) => c.did === alice)).toEqual({
        did: alice,
        outcome: 'verified',
        handle: 'alice.test',
        pdsChanged: true,
        cleared: null,
      });
      expect(snapshotJobs(db)).toEqual([{ did: alice, state: 'pending', reason: 'pds_migration', generation }]);
      expect(db.one("SELECT due_at FROM repo_jobs WHERE did = ? AND kind = 'snapshot'", alice)).toEqual({ due_at: t1 });
      expect(dueAt(db, 'snapshot')).toBe(t1);
      expect(db.one('SELECT pds, active, account_status FROM users WHERE did = ?', alice)).toEqual({
        pds: k.pds.Bob.origin,
        active: 1,
        account_status: 'active',
      });
      // Migration is not deactivation: Alice stays visible, her rows unchanged, until the
      // snapshot from the new PDS re-verifies them.
      expect(projection(db)).toEqual(before);
      expect(historyOf(m, alice)).toEqual(ALICE_HISTORY);
      expect(db.all("SELECT label, value FROM counters WHERE name = 'pds_changed'")).toEqual([
        { label: 'scheduled', value: 1 },
      ]);

      // The next sweep sees the same endpoint: no further snapshot request.
      await identitySweep(m, t1 + DAY);
      expect(snapshotJobs(db)).toEqual([{ did: alice, state: 'pending', reason: 'pds_migration', generation }]);
      expect(db.all("SELECT label, value FROM counters WHERE name = 'pds_changed'")).toEqual([
        { label: 'scheduled', value: 1 },
      ]);
    });
  });

  it('renamed handle verifies on the next identity sweep and resolves to the same DID with unchanged history', async () => {
    const k = await kit();
    const alice = k.users.Alice.did;
    const RENAMED = 'alice-renamed.test';

    await runInDurableObject(stubFor('sweep-rename'), async (i: HarnessDO) => {
      const db = i.db;
      const m = depsFor(db, k);
      await seedIndexed(db, m, k);
      await identitySweep(m, T0);
      expect(handles(db)[alice]).toBe('alice.test');
      const before = projection(db);
      const userBefore = db.one(
        'SELECT did, joined_at, active, generation, max_rev, stats_version FROM users WHERE did = ?',
        alice,
      );

      // Alice renames: the new handle publishes her DID; her document claims it.
      k.plc.setHandle(alice, RENAMED);
      k.doh.setTxt(`_atproto.${RENAMED}`, [`did=${alice}`]);
      k.handles.set(RENAMED, alice);
      // Until the next sweep the stored handle is the old one.
      await identitySweep(m, T0 + DAY - 1);
      expect(handles(db)[alice]).toBe('alice.test');

      k.resetCalls();
      const report = await identitySweep(m, T0 + DAY);
      expect(report.checked.find((c) => c.did === alice)).toEqual({
        did: alice,
        outcome: 'verified',
        handle: RENAMED,
        pdsChanged: false,
        cleared: null,
      });
      expect(k.plc.count(alice)).toBe(1);
      expect(handles(db)[alice]).toBe(RENAMED);

      // The new handle resolves to the same DID; the old one no longer verifies.
      expect(await resolveHandle(m, RENAMED)).toEqual({ status: 'ok', did: alice, handle: RENAMED });
      expect(await resolveHandle(m, 'alice.test')).toEqual({ status: 'mismatch' });
      expect(await profile(m, alice)).toMatchObject({ did: alice, handle: RENAMED, totalScrobbles: 7 });

      // Identity is the DID: history, follows, guards and the account row are unchanged.
      expect(projection(db)).toEqual(before);
      expect(
        db.one('SELECT did, joined_at, active, generation, max_rev, stats_version FROM users WHERE did = ?', alice),
      ).toEqual(userBefore);
      expect(historyOf(m, alice)).toEqual(ALICE_HISTORY);
      expect(snapshotJobs(db)).toEqual([]);
    });
  });

  it('a verified handle held by another account clears the older holder', async () => {
    const k = await kit();
    const alice = k.users.Alice.did;
    const bob = k.users.Bob.did;

    await runInDurableObject(stubFor('sweep-handle-conflict'), async (i: HarnessDO) => {
      const db = i.db;
      const m = depsFor(db, k);
      await seedIndexed(db, m, k);
      await identitySweep(m, T0);
      expect(handles(db)[alice]).toBe('alice.test');

      // Bob takes alice.test; Alice is not due for another check yet.
      k.plc.setHandle(bob, 'alice.test');
      k.doh.setTxt('_atproto.alice.test', [`did=${bob}`]);
      k.handles.set('alice.test', bob);
      db.run('UPDATE users SET handle_checked_at_ms = ? WHERE did != ?', T0 + DAY, bob);

      const report = await identitySweep(m, T0 + DAY);
      expect(report.checked).toEqual([
        { did: bob, outcome: 'verified', handle: 'alice.test', pdsChanged: false, cleared: alice },
      ]);
      expect(handles(db)).toEqual({ [alice]: null, [bob]: 'alice.test', [k.users.Carol.did]: 'carol.test' });
      expect(db.all("SELECT label, value FROM counters WHERE name = 'handle_conflict'")).toEqual([
        { label: '', value: 1 },
      ]);
      expect(historyOf(m, alice)).toEqual(ALICE_HISTORY);
      expect(historyOf(m, bob)).toEqual(['r09']);
    });
  });
});

describe('identity sweep edge cases', () => {
  it('a handle re-verify transport failure (DoH TXT and well-known 503) keeps the stored handle', async () => {
    const k = await kit();
    const alice = k.users.Alice.did;
    const bob = k.users.Bob.did;
    const carol = k.users.Carol.did;
    // alice.test's well-known endpoint fails with 503 while `wellKnownDown` is set.
    let wellKnownDown = false;
    let wellKnownCalls = 0;
    const transport = Object.assign(
      async (req: Request) => {
        const url = new URL(req.url);
        if (url.hostname === 'alice.test' && url.pathname === '/.well-known/atproto-did') {
          wellKnownCalls++;
          if (wellKnownDown) return new Response('unavailable', { status: 503 });
        }
        return k.transport(req);
      },
      { fixture: true as const, calls: k.transport.calls, hostnames: k.transport.hostnames },
    ) satisfies FixtureTransport;

    await runInDurableObject(stubFor('sweep-handle-transient'), async (i: HarnessDO) => {
      const db = i.db;
      const base = depsFor(db, k);
      const m: Deps = { ...base, transport, identity: cachedIdentityResolver(db, { transport, clock: k.clock }) };
      await seedIndexed(db, m, k);
      expect((await identitySweep(m, T0)).checked.map((c) => [c.did, c.outcome]).sort()).toEqual([
        [alice, 'verified'],
        [bob, 'verified'],
        [carol, 'verified'],
      ]);
      expect(handles(db)).toEqual({ [alice]: 'alice.test', [bob]: 'bob.test', [carol]: 'carol.test' });
      const before = projection(db);

      // Both handle transports for alice.test fail: DoH TXT answers 503, so does the well-known URL.
      k.doh.fail({ path: '_atproto.alice.test' }, { kind: 'status', status: 503 }, Number.POSITIVE_INFINITY);
      wellKnownDown = true;
      k.resetCalls();
      wellKnownCalls = 0;
      const report = await identitySweep(m, T0 + DAY);
      const aliceOutcome = report.checked.find((c) => c.did === alice);
      expect(aliceOutcome).toMatchObject({ did: alice, outcome: 'kept' });
      expect(report.checked.filter((c) => c.did !== alice).map((c) => c.outcome)).toEqual(['verified', 'verified']);
      // Both transports were tried (and failed), yet the stored handle is unchanged.
      expect(k.doh.count('_atproto.alice.test', 'TXT')).toBeGreaterThan(0);
      expect(wellKnownCalls).toBeGreaterThan(0);
      expect(handles(db)).toEqual({ [alice]: 'alice.test', [bob]: 'bob.test', [carol]: 'carol.test' });
      expect(db.one('SELECT handle_checked_at_ms AS t, pds FROM users WHERE did = ?', alice)).toEqual({
        t: T0 + DAY,
        pds: k.users.Alice.origin,
      });
      expect(db.all("SELECT label, value FROM counters WHERE name = 'handle_cleared'")).toEqual([]);
      expect(
        db.one<{ n: number }>("SELECT sum(value) AS n FROM counters WHERE name = 'identity_sweep_failed'")!.n,
      ).toBeGreaterThan(0);
      expect(projection(db)).toEqual(before);
      expect(snapshotJobs(db)).toEqual([]);

      // The transports recover: the next sweep verifies the handle again.
      k.doh.faults.clear();
      wellKnownDown = false;
      const again = await identitySweep(m, T0 + 2 * DAY);
      expect(again.checked.find((c) => c.did === alice)).toMatchObject({ outcome: 'verified', handle: 'alice.test' });
      expect(handles(db)[alice]).toBe('alice.test');
      expect(await profile(m, alice)).toMatchObject({ did: alice, handle: 'alice.test' });
    });
  });

  it('PDS-migration detection does not act on a non-fresh identity_cache entry before the first identity sweep', async () => {
    const k = await kit();
    const alice = k.users.Alice.did;
    const bob = k.users.Bob.did;

    await runInDurableObject(stubFor('sweep-pds-stale-cache'), async (i: HarnessDO) => {
      const db = i.db;
      const m = depsFor(db, k);
      // Indexed through the drain at T0: identity_cache entries from T0, users.pds not yet known.
      await seedIndexed(db, m, k);
      expect(db.all('SELECT did, pds FROM users ORDER BY did').map((r) => (r as { pds: string | null }).pds)).toEqual([
        null,
        null,
        null,
      ]);
      expect(db.one('SELECT pds, fetched_at_ms FROM identity_cache WHERE did = ?', alice)).toEqual({
        pds: k.users.Alice.origin,
        fetched_at_ms: T0,
      });

      // Ten minutes on (the 5-minute TTL has passed), Alice's document names another PDS.
      k.clock.advance(10 * 60_000);
      const t1 = k.clock.nowMs();
      // Bob's entry is refreshed now (fresh) and his document then moves him too.
      expect((await resolveIdentity(m, bob)).ok).toBe(true);
      expect(db.one('SELECT fetched_at_ms FROM identity_cache WHERE did = ?', bob)).toEqual({ fetched_at_ms: t1 });
      k.plc.setPds(alice, k.pds.Carol.origin);
      k.plc.setPds(bob, k.pds.Carol.origin);

      const report = await identitySweep(m, t1);
      // Alice: the only evidence of a different PDS was an expired cache entry. No migration.
      expect(report.checked.find((c) => c.did === alice)).toMatchObject({ outcome: 'verified', pdsChanged: false });
      // Bob: a fresh entry named his previous PDS, so the change is acted on.
      expect(report.checked.find((c) => c.did === bob)).toMatchObject({ outcome: 'verified', pdsChanged: true });
      const generation = (did: string) =>
        db.one<{ generation: number }>('SELECT generation FROM users WHERE did = ?', did)!.generation;
      expect(snapshotJobs(db)).toEqual([
        { did: bob, state: 'pending', reason: 'pds_migration', generation: generation(bob) },
      ]);
      expect(db.all("SELECT label, value FROM counters WHERE name = 'pds_changed'")).toEqual([
        { label: 'scheduled', value: 1 },
      ]);
      // Both now record the endpoint their document names.
      expect(db.one('SELECT pds FROM users WHERE did = ?', alice)).toEqual({ pds: k.pds.Carol.origin });
      expect(db.one('SELECT pds FROM users WHERE did = ?', bob)).toEqual({ pds: k.pds.Carol.origin });
      expect(historyOf(m, alice)).toEqual(ALICE_HISTORY);
    });
  });
});

baselineSources.worker/test/ingest/verify-drain.test.ts:
// W3-04 verify-drain.ts: hints → identity → getRecord proof → verify → apply,
// against real DO SQLite and the fixture network (real signed repositories on
// fake PDSs, fake PLC and DoH, the production SafeFetch policy). Proves
// M5.3.3/pending_confirmed (a confirmed follow becomes an edge only once its
// proof applies), M3.3.3/external_delete, M4.1.3/update_delete,
// M4.1.2/key_rotation and M1.3.4/concurrent_writes. Every expectation is
// hardcoded or comes from the fixture signer, never from the code under test.

import { runInDurableObject } from 'cloudflare:test';
import { env } from 'cloudflare:workers';
import type { FakePds } from '@atmusic/atproto/test-support/fake-pds';
import { testKey } from '@atmusic/atproto/test-support/keys';
import { type FixtureKit, followRkey } from '@atmusic/atproto/test-support/read-models';
import { carResponse, type FixtureTransport } from '@atmusic/atproto/test-support/router-transport';
import { SignedRepo } from '@atmusic/atproto/test-support/signed-repo';
import { describe, expect, it } from 'vitest';
import type { Db } from '../../src/do/db';
import { resolveIdentity } from '../../src/do/ingest/identity-cache';
import { drain, drainState } from '../../src/do/ingest/verify-drain';
import { visibleFollowEdge, visibleScrobblesFrom } from '../../src/do/read/visibility';
import { runDue, type TimerHandlers } from '../../src/do/timers';
import type { HarnessDO } from '../harness/harness-do';
import { seedUser } from '../write/support';
import {
  counterValue,
  depsFor,
  enqueue,
  GET_RECORD,
  hint,
  hintRows,
  kit,
  protectedTables,
  snapshotJobs,
} from './drain-support';

const stubFor = (name: string) => env.HARNESS.get(env.HARNESS.idFromName(name));

const T0 = Date.parse('2026-01-15T12:00:00Z');
const FUTURE_REASON = 'listenedAt: timestamp must be between 1970-01-01 and receipt time plus 300 seconds';

function scrobble(k: FixtureKit, listenedAt: string, extra: Record<string, unknown> = {}) {
  return {
    $type: k.collections.scrobble,
    artist: 'Björk',
    track: 'Hyperballad',
    album: 'Post',
    listenedAt,
    createdAt: '2026-01-15T11:00:00Z',
    ...extra,
  };
}

function rows(db: Db, did?: string) {
  return db.all<{ uri: string; revision: string; cid: string; artist: string; track: string }>(
    `SELECT uri, revision, cid, artist, track FROM scrobbles ${did ? 'WHERE did = ?' : ''} ORDER BY uri`,
    ...(did ? [did] : []),
  );
}

function state(db: Db, uri: string) {
  return db.one('SELECT revision, cid, state, reason FROM record_state WHERE uri = ?', uri);
}

function visible(db: Db, did: string): string[] {
  return db
    .all<{ uri: string }>(`SELECT s.uri FROM ${visibleScrobblesFrom()} WHERE s.did = ? ORDER BY s.uri`, did)
    .map((r) => r.uri);
}

function follows(db: Db) {
  return db.all('SELECT uri, cid, actor, subject, revision, created_at, indexed_at FROM follows ORDER BY uri');
}

/** Subjects of `actor`'s visible follow edges (the following list). */
function following(db: Db, actor: string): string[] {
  return db
    .all<{ subject: string }>(
      `SELECT f.subject FROM follows f WHERE f.actor = ? AND ${visibleFollowEdge('f')} ORDER BY f.subject`,
      actor,
    )
    .map((r) => r.subject);
}

/** Actors of the visible follow edges to `subject` (the followers list). */
function followers(db: Db, subject: string): string[] {
  return db
    .all<{ actor: string }>(
      `SELECT f.actor FROM follows f WHERE f.subject = ? AND ${visibleFollowEdge('f')} ORDER BY f.actor`,
      subject,
    )
    .map((r) => r.actor);
}

const getRecordCalls = (pds: FakePds, rkey?: string) =>
  pds.calls.filter({ nsid: GET_RECORD }).filter((c) => rkey === undefined || c.params.rkey?.[0] === rkey).length;

/** Let pending microtasks and I/O callbacks run (no clock involved). */
const tick = () => new Promise<void>((resolve) => setTimeout(resolve, 0));

describe('verify drain', () => {
  it('known active DID hint → one getRecord call → row applied with receipt-time validation', async () => {
    const k = await kit();
    const alice = k.users.Alice.did;
    const S = k.collections.scrobble;
    // Exactly at the receipt bound (+300 s) and one second past it.
    const atBound = await k.externalPut('Alice', S, 'r1', scrobble(k, '2026-01-15T12:05:00Z'));
    const pastBound = await k.externalPut('Alice', S, 'r2', scrobble(k, '2026-01-15T12:05:01Z', { track: 'Isobel' }));
    const r1Cid = atBound.ops[0]!.cid!;
    k.resetCalls();

    await runInDurableObject(stubFor('drain-known'), async (i: HarnessDO) => {
      const db = i.db;
      const m = depsFor(db, k);
      seedUser(db, alice);
      // Both hints received at T0; the drain runs ten minutes later, so only the
      // receipt time (not the drain time) can exclude r2.
      enqueue(db, [hint(k, alice, S, 'r1', { hintRev: atBound.rev })]);
      k.clock.advance(600_000);
      const now = k.clock.nowMs();
      const first = await drain(m, now);
      expect(first.outcomes).toEqual([{ uri: `at://${alice}/${S}/r1`, outcome: 'applied' }]);
      expect(getRecordCalls(k.pds.Alice)).toBe(1);
      expect(k.pds.Alice.calls.filter({ nsid: GET_RECORD })[0]!.params).toEqual({
        did: [alice],
        collection: [S],
        rkey: ['r1'],
      });
      // The head served is r2's commit, which is newer than r1's own: present at that head.
      const head = k.repos.Alice.head!;
      expect(rows(db, alice)).toEqual([
        { uri: `at://${alice}/${S}/r1`, revision: head.rev, cid: r1Cid, artist: 'Björk', track: 'Hyperballad' },
      ]);
      expect(state(db, `at://${alice}/${S}/r1`)).toEqual({
        revision: head.rev,
        cid: r1Cid,
        state: 'present',
        reason: null,
      });
      expect(db.one('SELECT max_rev, stats_version, last_activity_ms FROM users WHERE did = ?', alice)).toEqual({
        max_rev: head.rev,
        stats_version: 1,
        last_activity_ms: now,
      });
      expect(db.one('SELECT indexed_at FROM scrobbles')).toEqual({ indexed_at: '2026-01-15T12:10:00.000000000Z' });
      expect(hintRows(db)).toEqual([]);
      expect(visible(db, alice)).toEqual([`at://${alice}/${S}/r1`]);
      // The proof's commit is remembered for the signature cache.
      expect(db.all('SELECT did, commit_cid, rev FROM verified_commits')).toEqual([
        { did: alice, commit_cid: head.cid, rev: head.rev },
      ]);

      // r2, received at T0 + 600 s - 600 s = T0 as well, is one second past its receipt bound.
      enqueue(db, [hint(k, alice, S, 'r2', { receiptMs: T0, dueAt: now })]);
      const second = await drain(m, now);
      expect(second.outcomes).toEqual([{ uri: `at://${alice}/${S}/r2`, outcome: 'excluded', detail: FUTURE_REASON }]);
      expect(getRecordCalls(k.pds.Alice)).toBe(2);
      expect(getRecordCalls(k.pds.Alice, 'r2')).toBe(1);
      expect(state(db, `at://${alice}/${S}/r2`)).toEqual({
        revision: head.rev,
        cid: pastBound.ops[0]!.cid,
        state: 'excluded',
        reason: FUTURE_REASON,
      });
      expect(rows(db, alice).map((r) => r.uri)).toEqual([`at://${alice}/${S}/r1`]);
      expect(counterValue(db, 'excluded', FUTURE_REASON)).toBe(1);
      // The identity was resolved once and then served from identity_cache.
      expect(k.plc.count(alice)).toBe(1);

      // M5.3.3/pending_confirmed: a follow of Bob confirmed on Alice's PDS (the SPA's
      // queued write) is not an edge until its proof applies.
      const bob = k.users.Bob.did;
      const F = k.collections.follow;
      seedUser(db, bob);
      const rkey = await followRkey(bob);
      const followUri = `at://${alice}/${F}/${rkey}`;
      const followed = await k.externalPut('Alice', F, rkey, {
        $type: F,
        subject: bob,
        createdAt: '2026-01-15T12:09:00Z',
      });
      const followCid = followed.ops[0]!.cid!;
      expect(follows(db)).toEqual([]);
      expect(following(db, alice)).toEqual([]);
      expect(followers(db, bob)).toEqual([]);
      expect(state(db, followUri)).toBeNull();

      enqueue(db, [hint(k, alice, F, rkey, { hintRev: followed.rev })]);
      const third = await drain(m, now);
      expect(third.outcomes).toEqual([{ uri: followUri, outcome: 'applied' }]);
      expect(getRecordCalls(k.pds.Alice)).toBe(3);
      expect(getRecordCalls(k.pds.Alice, rkey)).toBe(1);
      expect(k.pds.Alice.calls.filter({ nsid: GET_RECORD })[2]!.params).toEqual({
        did: [alice],
        collection: [F],
        rkey: [rkey],
      });
      expect(follows(db)).toEqual([
        {
          uri: followUri,
          cid: followCid,
          actor: alice,
          subject: bob,
          revision: followed.rev,
          created_at: '2026-01-15T12:09:00.000000000Z',
          indexed_at: '2026-01-15T12:10:00.000000000Z',
        },
      ]);
      expect(state(db, followUri)).toEqual({ revision: followed.rev, cid: followCid, state: 'present', reason: null });
      expect(following(db, alice)).toEqual([bob]);
      expect(followers(db, bob)).toEqual([alice]);
      expect(db.one('SELECT max_rev FROM users WHERE did = ?', alice)).toEqual({ max_rev: followed.rev });
      expect(hintRows(db)).toEqual([]);
      // The scrobble projection is unchanged by the follow.
      expect(rows(db, alice).map((r) => r.uri)).toEqual([`at://${alice}/${S}/r1`]);
    });
  });

  it('deleted record with exclusion proof → absent and removed from views', async () => {
    const k = await kit();
    const alice = k.users.Alice.did;
    const S = k.collections.scrobble;
    const uri = `at://${alice}/${S}/r1`;
    await k.externalPut('Alice', S, 'r1', scrobble(k, '2026-01-15T11:30:00Z'));
    k.resetCalls();

    await runInDurableObject(stubFor('drain-delete'), async (i: HarnessDO) => {
      const db = i.db;
      const m = depsFor(db, k);
      seedUser(db, alice);
      enqueue(db, [hint(k, alice, S, 'r1')]);
      expect((await drain(m, k.clock.nowMs())).outcomes).toEqual([{ uri, outcome: 'applied' }]);
      expect(visible(db, alice)).toEqual([uri]);
      const statsBefore = db.one<{ stats_version: number }>('SELECT stats_version FROM users WHERE did = ?', alice)!;

      // An external app deletes it; the PDS serves a signed exclusion proof.
      const deletion = await k.externalDelete('Alice', S, 'r1');
      k.clock.advance(5_000);
      enqueue(db, [hint(k, alice, S, 'r1', { hintRev: deletion.rev })]);
      expect((await drain(m, k.clock.nowMs())).outcomes).toEqual([{ uri, outcome: 'absent' }]);
      expect(getRecordCalls(k.pds.Alice)).toBe(2);

      expect(rows(db)).toEqual([]);
      expect(state(db, uri)).toEqual({ revision: deletion.rev, cid: null, state: 'absent', reason: null });
      expect(visible(db, alice)).toEqual([]);
      expect(db.one('SELECT stats_version, max_rev FROM users WHERE did = ?', alice)).toEqual({
        stats_version: statsBefore.stats_version + 1,
        max_rev: deletion.rev,
      });
      expect(hintRows(db)).toEqual([]);
      expect(snapshotJobs(db)).toEqual([]);
    });
  });

  it('RecordNotFound without CAR schedules snapshot and does not delete', async () => {
    const k = await kit();
    const alice = k.users.Alice.did;
    const S = k.collections.scrobble;
    const uri = `at://${alice}/${S}/r1`;
    const put = await k.externalPut('Alice', S, 'r1', scrobble(k, '2026-01-15T11:30:00Z'));
    k.resetCalls();

    await runInDurableObject(stubFor('drain-record-not-found'), async (i: HarnessDO) => {
      const db = i.db;
      const m = depsFor(db, k);
      const generation = seedUser(db, alice);
      enqueue(db, [hint(k, alice, S, 'r1')]);
      await drain(m, k.clock.nowMs());
      const projected = { rows: rows(db), state: state(db, uri), user: db.all('SELECT * FROM users') };
      expect(projected.rows).toEqual([
        { uri, revision: put.rev, cid: put.ops[0]!.cid, artist: 'Björk', track: 'Hyperballad' },
      ]);

      // The record is deleted, but this PDS answers RecordNotFound instead of a proof.
      await k.externalDelete('Alice', S, 'r1');
      k.pds.Alice.noExclusionProof = true;
      k.clock.advance(1_000);
      enqueue(db, [hint(k, alice, S, 'r1')]);
      const report = await drain(m, k.clock.nowMs());
      expect(report.outcomes).toEqual([{ uri, outcome: 'snapshot_scheduled', detail: 'record_not_found' }]);
      expect(k.pds.Alice.calls.filter({ nsid: GET_RECORD }).map((c) => c.status)).toEqual([200, 400]);

      // Unverified absence deletes nothing: row, record_state and user are byte-identical.
      expect({ rows: rows(db), state: state(db, uri), user: db.all('SELECT * FROM users') }).toEqual(projected);
      expect(visible(db, alice)).toEqual([uri]);
      expect(snapshotJobs(db)).toEqual([{ did: alice, state: 'pending', generation, reason: 'record_not_found' }]);
      expect(hintRows(db)).toEqual([]);
      expect(counterValue(db, 'snapshot_scheduled', 'record_not_found')).toBe(1);
    });
  });

  it('25 hints for one DID collapse into one snapshot job', async () => {
    const k = await kit();
    const alice = k.users.Alice.did;
    const bob = k.users.Bob.did;
    const S = k.collections.scrobble;
    k.resetCalls();

    await runInDurableObject(stubFor('drain-coalesce'), async (i: HarnessDO) => {
      const db = i.db;
      const m = depsFor(db, k);
      const aliceGen = seedUser(db, alice);
      seedUser(db, bob);
      const rkeys = (n: number) => Array.from({ length: n }, (_, j) => `r${String(j).padStart(2, '0')}`);
      enqueue(
        db,
        rkeys(25).map((r) => hint(k, alice, S, r)),
      );
      // 24 for Bob stay below the threshold and are worked one by one (absent records).
      enqueue(
        db,
        rkeys(24).map((r) => hint(k, bob, S, r)),
      );

      const report = await drain(m, k.clock.nowMs());
      const byOutcome = (o: string) => report.outcomes.filter((x) => x.outcome === o).length;
      expect(report.claimed).toBe(49);
      expect(byOutcome('coalesced')).toBe(1);
      expect(report.outcomes.find((x) => x.outcome === 'coalesced')).toEqual({
        uri: `at://${alice}/${S}/r00`,
        outcome: 'coalesced',
        detail: '25',
      });
      expect(byOutcome('skipped')).toBe(24);
      expect(byOutcome('absent')).toBe(24);

      // Alice: no fetch at all, one snapshot job at her generation, no hint left.
      expect(getRecordCalls(k.pds.Alice)).toBe(0);
      expect(k.plc.count(alice)).toBe(0);
      expect(snapshotJobs(db)).toEqual([{ did: alice, state: 'pending', generation: aliceGen, reason: 'coalesced' }]);
      expect(db.one('SELECT count(*) AS n FROM hints WHERE did = ?', alice)).toEqual({ n: 0 });
      expect(counterValue(db, 'coalesced')).toBe(1);
      // Bob: 24 individual proofs.
      expect(getRecordCalls(k.pds.Bob)).toBe(24);
      expect(db.one("SELECT count(*) AS n FROM record_state WHERE did = ? AND state = 'absent'", bob)).toEqual({
        n: 24,
      });
      expect(hintRows(db)).toEqual([]);
    });
  });

  it('coalescing during a walk keeps its frontier and lease and records one rescan; a hint flood never restarts it', async () => {
    const k = await kit();
    const alice = k.users.Alice.did;
    const S = k.collections.scrobble;
    const H0 = k.repos.Alice.head!.cid; // the head the walk started from
    // 25 records written after H0; their hints are what coalescing deletes.
    const ops = Array.from({ length: 25 }, (_, j) => ({
      action: 'put' as const,
      collection: S,
      rkey: `n${String(j).padStart(2, '0')}`,
      record: scrobble(k, '2026-01-15T11:00:00Z', { track: `New ${j}` }),
    }));
    await k.repos.Alice.writes(ops);
    expect(k.repos.Alice.head!.cid).not.toBe(H0);
    k.resetCalls();

    await runInDurableObject(stubFor('drain-coalesce-rescan'), async (i: HarnessDO) => {
      const db = i.db;
      const m = depsFor(db, k);
      const generation = seedUser(db, alice);
      // A many-slice walk paused between slices at H0 (resumes its frontier when due).
      db.run(
        `INSERT INTO repo_jobs(did, kind, state, generation, reason, head_cid, frontier_json, restarts, due_at, updated_at_ms)
         VALUES (?, 'snapshot', 'pending', ?, 'admission', ?, '{"lastKey":"x"}', 0, ?, ?)`,
        alice,
        generation,
        H0,
        T0 + 2_000,
        T0 - 7,
      );
      const users = db.all('SELECT * FROM users');
      const job = () =>
        db.one(
          `SELECT state, generation, reason, head_cid, frontier_json, restarts, due_at, attempts, updated_at_ms
           FROM repo_jobs WHERE did = ? AND kind = 'snapshot'`,
          alice,
        );
      const flood = async () => {
        enqueue(
          db,
          ops.map((o) => hint(k, alice, S, o.rkey, { source: 'notify' })),
        );
        const report = await drain(m, k.clock.nowMs());
        expect(report.outcomes.filter((o) => o.outcome === 'coalesced')).toEqual([
          { uri: expect.any(String), outcome: 'coalesced', detail: '25' },
        ]);
        expect(hintRows(db)).toEqual([]);
      };

      await flood();
      expect(getRecordCalls(k.pds.Alice)).toBe(0);
      // The paused walk keeps its frontier, head, epoch, due time and lease; one rescan request.
      expect(job()).toEqual({
        state: 'pending',
        generation,
        reason: 'admission',
        head_cid: H0,
        frontier_json: '{"lastKey":"x"}',
        restarts: 0,
        due_at: T0 + 2_000,
        attempts: 1,
        updated_at_ms: T0 - 7,
      });

      // A slice in flight at H0 (lease token T0 - 7): a flood every few seconds, as an
      // unauthenticated notify sender could, never takes the row from it.
      db.run(`UPDATE repo_jobs SET state = 'running' WHERE did = ?`, alice);
      for (let n = 0; n < 5; n++) {
        k.clock.advance(3_000);
        await flood();
      }
      expect(job()).toEqual({
        state: 'running',
        generation,
        reason: 'admission',
        head_cid: H0,
        frontier_json: '{"lastKey":"x"}',
        restarts: 0,
        due_at: T0 + 2_000,
        attempts: 6,
        updated_at_ms: T0 - 7,
      });
      // So that slice's guarded frontier write (W4-01 contract) still lands.
      expect(
        db.all(
          `UPDATE repo_jobs SET frontier_json = '{"lastKey":"y"}', updated_at_ms = max(updated_at_ms + 1, ?)
           WHERE did = ? AND kind = 'snapshot' AND state = 'running' AND generation = ? AND updated_at_ms = ?
           RETURNING did`,
          k.clock.nowMs(),
          alice,
          generation,
          T0 - 7,
        ),
      ).toEqual([{ did: alice }]);
      expect(getRecordCalls(k.pds.Alice)).toBe(0);
      expect(counterValue(db, 'coalesced')).toBe(6);
      expect(counterValue(db, 'snapshot_rescan', 'coalesced')).toBe(6);
      expect(counterValue(db, 'snapshot_scheduled', 'coalesced')).toBe(0);

      // A failed walk (repository_changed, in backoff): floods keep its backoff and restarts.
      db.run(
        `UPDATE repo_jobs SET state = 'failed', restarts = 6, failure_code = 'repository_changed', due_at = ?,
           frontier_json = NULL, head_cid = NULL, attempts = 0 WHERE did = ?`,
        T0 + 3_600_000,
        alice,
      );
      k.clock.advance(3_000);
      await flood();
      expect(
        db.one(
          `SELECT state, restarts, failure_code, due_at, attempts FROM repo_jobs WHERE did = ? AND kind = 'snapshot'`,
          alice,
        ),
      ).toEqual({
        state: 'failed',
        restarts: 6,
        failure_code: 'repository_changed',
        due_at: T0 + 3_600_000,
        attempts: 0,
      });
      expect(db.all('SELECT * FROM users')).toEqual(users);
    });
  });

  it('a key change while a fetched proof verifies under the old key leaves verified_commits empty', async () => {
    const k = await kit();
    const alice = k.users.Alice.did;
    const S = k.collections.scrobble;
    const uri = `at://${alice}/${S}/r1`;
    const put = await k.externalPut('Alice', S, 'r1', scrobble(k, '2026-01-15T11:30:00Z'));
    expect(k.repos.Alice.head!.signedBy).toBe(k.keys.alice.didKey);
    k.resetCalls();

    await runInDurableObject(stubFor('drain-key-race'), async (i: HarnessDO) => {
      const db = i.db;
      const m = depsFor(db, k);
      seedUser(db, alice);
      // The drain reads the cached key K1, then its getRecord is held at the gate.
      let open!: () => void;
      const gate = new Promise<void>((resolve) => {
        open = resolve;
      });
      const car = await k.repos.Alice.getRecordCar(S, 'r1'); // signed by K1
      k.pds.Alice.fail(
        { nsid: GET_RECORD },
        {
          kind: 'respond',
          respond: async () => {
            await gate;
            return carResponse(car);
          },
        },
      );
      enqueue(db, [hint(k, alice, S, 'r1')]);
      const alarm = drain(m, k.clock.nowMs());
      while (k.pds.Alice.faults.pending > 0) await tick();
      expect(db.one('SELECT signing_key FROM identity_cache WHERE did = ?', alice)).toEqual({
        signing_key: k.keys.alice.didKey,
      });

      // Meanwhile the DID rotates to K2 and another worker's fresh resolution stores it
      // (putIdentity forgets the DID's verified commits, of which there are none yet).
      k.plc.rotateKey(alice, k.keys.aliceRotated);
      const fresh = await resolveIdentity(m, alice, { fresh: true });
      expect(fresh.ok && fresh.identity.signingKey).toBe(k.keys.aliceRotated.didKey);

      // The held proof verifies under K1 after the change: it is not remembered, so no
      // later K1-signed CAR rooted at that commit can skip its signature check.
      open();
      expect((await alarm).outcomes).toEqual([{ uri, outcome: 'applied' }]);
      expect(rows(db)).toEqual([
        { uri, revision: put.rev, cid: put.ops[0]!.cid, artist: 'Björk', track: 'Hyperballad' },
      ]);
      expect(db.all('SELECT * FROM verified_commits')).toEqual([]);
      expect(getRecordCalls(k.pds.Alice)).toBe(1);

      // The same commit served again is verified in full under the current key K2: it fails closed.
      k.pds.Alice.fail({ nsid: GET_RECORD }, { kind: 'respond', respond: () => carResponse(car) });
      k.clock.advance(1_000);
      enqueue(db, [hint(k, alice, S, 'r1')]);
      const again = await drain(m, k.clock.nowMs());
      expect(again.outcomes).toEqual([{ uri, outcome: 'verify_failed', detail: 'bad_signature' }]);
      expect(counterValue(db, 'verify_failed', 'bad_signature')).toBe(1);
      expect(db.all('SELECT * FROM verified_commits')).toEqual([]);

      // With the key unchanged, a verified commit is remembered as before (under K2): the PDS
      // re-signs with K2, and the backed-off r1 hint and a new r2 hint both prove at that head.
      k.pds.Alice.faults.clear();
      await k.rotateKey('Alice', k.keys.aliceRotated);
      const put2 = await k.externalPut('Alice', S, 'r2', scrobble(k, '2026-01-15T11:31:00Z'));
      k.clock.advance(1_000);
      enqueue(db, [hint(k, alice, S, 'r2')]);
      const last = await drain(m, k.clock.nowMs());
      expect(last.outcomes.map((o) => `${o.uri} ${o.outcome}`).sort()).toEqual([
        `${uri} applied`,
        `at://${alice}/${S}/r2 applied`,
      ]);
      expect(db.all('SELECT did, rev FROM verified_commits')).toEqual([{ did: alice, rev: put2.rev }]);
      expect(hintRows(db)).toEqual([]);
    });
  });

