  expect(running.status).toBe(200);
  expect(schemas.Profile(running.body)).toBe('valid');
  expect(running.body).toEqual({
    did: BOB,
    handle: 'bob.test',
    joinedAt: NOW,
    indexedAt: null,
    totalScrobbles: 0,
