    tracks: [track('Björk', 'Jóga', 2), track('Radiohead', 'No Surprises', 1), track('Radiohead', 'Weird Fishes', 1)],
    albums: [
      album('Björk', 'Homogenic', 2),
      album('Radiohead', 'In Rainbows', 1),
      album('Radiohead', 'OK Computer', 1),
    ],
  },
  '30d': {
